import re
import subprocess
from pathlib import Path
pattern = r'\\b(?:mature\\w*|directMaturePointNonempty)\\b'
branches = ['main', 'refs/remotes/github/issue-134-simultaneous-polynomial-measurements', 'issue-135-low-degree-soundness-transport', 'issue-210-general-k-combining-reduction']
for branch in branches:
    revision = subprocess.check_output(['git', 'rev-parse', branch], text=True).strip()
    result = subprocess.run(['git', 'grep', '-n', '-E', pattern, revision, '--', 'MIPStarRE', 'blueprint/src', 'blueprint/lean_decls'], text=True, capture_output=True)
    assert result.returncode in (0, 1), result.stderr
    matches = result.stdout.splitlines()
    consumers = [line for line in matches if not re.search(r':alias (?:mature\\w*|directMaturePointNonempty) := ', line)]
    print(f'{branch} @ {revision}: {len(matches)} matches; {len(consumers)} consumers')
    for line in consumers:
        print(line)
for root in ['/home/drx/MIPStarRE-qpbt', '/home/drx/MIPStarRE-qpbt/.worktrees/issue-135-low-degree-soundness-transport', '/home/drx/MIPStarRE-qpbt/.worktrees/issue-210-general-k-combining-reduction']:
    aliases = 0
    consumers = []
    for folder in ['MIPStarRE', 'blueprint/src']:
        for path in (Path(root) / folder).rglob('*'):
            if path.is_file() and path.suffix in ('.lean', '.tex'):
                for number, line in enumerate(path.read_text().splitlines(), 1):
                    if re.search(pattern, line):
                        if re.match(r'alias (?:mature\\w*|directMaturePointNonempty) := ', line):
                            aliases += 1
                        else:
                            consumers.append(f'{path}:{number}: {line}')
    print(f'Read-only working tree {root}: {aliases} aliases; {len(consumers)} consumers')
    for line in consumers:
        print(line)
